import java.io.*;
import java.util.*;

public class Main {
    static int[] parent;
    static int[] size;

    static int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    static boolean union(int a, int b) {
        int ra = find(a);
        int rb = find(b);
        if (ra == rb) return false;

        if (size[ra] < size[rb]) {
            int temp = ra;
            ra = rb;
            rb = temp;
        }

        parent[rb] = ra;
        size[ra] += size[rb];
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();

        long[] order = new long[n];
        for (int i = 0; i < n; i++) {
            long height = fs.nextInt();
            order[i] = (height << 20) | i;
        }
        Arrays.sort(order);

        parent = new int[n];
        size = new int[n];
        boolean[] active = new boolean[n];

        int components = 0;
        int maxComponents = 0;
        int i = n - 1;

        while (i >= 0) {
            long height = order[i] >>> 20;
            int j = i;

            while (j >= 0 && (order[j] >>> 20) == height) {
                int index = (int) (order[j] & ((1 << 20) - 1));
                active[index] = true;
                parent[index] = index;
                size[index] = 1;
                components++;
                j--;
            }

            for (int k = j + 1; k <= i; k++) {
                int index = (int) (order[k] & ((1 << 20) - 1));

                if (index > 0 && active[index - 1] && union(index, index - 1)) {
                    components--;
                }
                if (index + 1 < n && active[index + 1] && union(index, index + 1)) {
                    components--;
                }
            }

            maxComponents = Math.max(maxComponents, components);
            i = j;
        }

        System.out.println(maxComponents + 1);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        FastScanner(InputStream in) {
            this.in = in;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int value = 0;
            while (c > ' ') {
                value = value * 10 + (c - '0');
                c = read();
            }
            return value;
        }
    }
}
